package cpw.mods.fml.common.gameevent;import net.minecraft.entity.player.EntityPlayer;import net.minecraft.item.ItemStack;public class PlayerEvent extends cpw.mods.fml.common.eventhandler.Event {public final EntityPlayer player;public PlayerEvent(EntityPlayer p){player=p;}public static class ItemCraftedEvent extends PlayerEvent {public final ItemStack crafting;public ItemCraftedEvent(EntityPlayer p,ItemStack s){super(p);crafting=s;}}public static class ItemPickupEvent extends PlayerEvent {public final Picked pickedUp;public ItemPickupEvent(EntityPlayer p,ItemStack s){super(p);pickedUp=new Picked(s);}public record Picked(ItemStack stack){public ItemStack getEntityItem(){return stack;}}} }
